// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;

    function setUp() public {
        c = new demo();
    }

    function testFuzz_property(address from, address[] memory tos, uint256 v) public {
        // Keep the input admissible but wide: non-empty list, distinct random recipients.
        vm.assume(tos.length > 0);
        // Bound the list length so the recorder loop stays finite and gas-bounded.
        uint256 n = tos.length;
        if (n > 8) {
            n = 8;
        }
        address[] memory recipients = new address[](n);
        for (uint256 i = 0; i < n; i++) {
            recipients[i] = tos[i];
        }

        Recorder rec = new Recorder();
        bool ok = c.transfer(from, address(rec), recipients, v);

        // General rule: the callee must have observed exactly one transferFrom per recipient,
        // with the exact same (from, to, amount) triple for each list element, in the same order.
        bool matches = rec.count() == recipients.length;
        for (uint256 i = 0; i < recipients.length && matches; i++) {
            (address seenFrom, address seenTo, uint256 seenValue) = rec.calls(i);
            matches = seenFrom == from && seenTo == recipients[i] && seenValue == v;
        }

        assertTrue(ok && matches);
    }
}

contract Recorder {
    struct Call {
        address from;
        address to;
        uint256 value;
    }

    Call[] private _calls;

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        _calls.push(Call(from, to, value));
        return true;
    }

    function count() external view returns (uint256) {
        return _calls.length;
    }

    function calls(uint256 i) external view returns (address, address, uint256) {
        Call memory entry = _calls[i];
        return (entry.from, entry.to, entry.value);
    }
}
